import { createServer } from 'vite'
import { watch } from 'chokidar'
import { once } from 'node:events'
import { isAbsolute, join, relative, sep } from 'node:path'
import { appRoot, repositoryRoot } from '../lib/paths'
import { publicPackageBuildInputs } from '../lib/package-inputs'
import type { DependencySnapshot } from './dependencies'
import type { DesktopDependency } from './dependencies'
import type { DependencyResolver } from './dependencies'

/** Vite and the public-package snapshot serving this development session. */
export interface DevelopmentRenderer {
  readonly url: string
  /** Resolve candidate exports through Vite's current client environment, including after restart. */
  resolveDependency: DependencyResolver
  /** Change public imports after a successful package build and refresh loaded documents. */
  adopt(snapshot: DependencySnapshot): Promise<void>
  /** Observe runtime and package inputs; returns the watcher subscription cleanup. */
  watch(listener: (change: 'runtime' | 'public-package') => void): () => void
  close(): Promise<void>
}

function contains(parent: string, path: string): boolean {
  const child = relative(parent, path)
  return child !== '..' && !child.startsWith(`..${sep}`) && !isAbsolute(child)
}

/** Start the renderer server and retain its current public-package resolution until close(). */
export async function startRenderer(
  members: DesktopDependency[],
  snapshotDirectory: string,
): Promise<DevelopmentRenderer> {
  let snapshot: DependencySnapshot | undefined
  const listeners = new Set<(change: 'runtime' | 'public-package') => void>()
  const packageInputs = (
    await Promise.all(members.map((member) => publicPackageBuildInputs(member.path)))
  ).flat()
  const runtimeInputs = [
    ...['main', 'preload', 'extension-host', 'shared'].map((name) => join(appRoot, 'src', name)),
    join(appRoot, 'native'),
    join(appRoot, 'assets'),
    ...['main', 'preload', 'extension-host', 'renderer'].map((name) =>
      join(appRoot, 'config', 'vite', `vite.config.${name}.ts`),
    ),
    join(appRoot, 'package.json'),
    join(repositoryRoot, 'pnpm-lock.yaml'),
  ]

  /** Forward owned source changes from each watcher created when Vite starts or restarts. */
  function changed(_event: string, path: string): void {
    let change: 'runtime' | 'public-package'
    if (packageInputs.some((input) => contains(input, path))) {
      change = 'public-package'
    } else if (runtimeInputs.some((input) => contains(input, path))) {
      change = 'runtime'
    } else {
      return
    }
    for (const listener of listeners) listener(change)
  }

  const server = await createServer({
    configFile: join(appRoot, 'config', 'vite', 'vite.config.renderer.ts'),
    mode: 'development',
    optimizeDeps: { exclude: members.map((member) => member.name) },
    plugins: [
      {
        name: 'desktop-public-dependency-snapshots',
        enforce: 'pre',
        async resolveId(source, importer, options) {
          // Imports inside a snapshot keep that generation's package resolution.
          if (importer && contains(snapshotDirectory, importer)) return null
          const specifier = source.replace(/[?#].*$/, '')
          const member = members.find(
            ({ name }) => specifier === name || specifier.startsWith(`${name}/`),
          )
          if (!member) return null

          const packageRoot = snapshot?.packages.get(member.name)
          if (!packageRoot) throw new Error('Public dependencies are not ready')
          return this.resolve(source, join(packageRoot, 'package.json'), {
            ...options,
            skipSelf: true,
          })
        },
      },
    ],
  })

  const inputWatcher = watch([...packageInputs, ...runtimeInputs], { ignoreInitial: true })
  const inputReady = once(inputWatcher, 'ready')
  inputWatcher.on('all', changed)

  try {
    await inputReady
    await server.listen()
    const initialUrl = server.resolvedUrls?.local[0]
    if (!initialUrl) throw new Error('Renderer server did not publish a listening address')
    let url = initialUrl

    return {
      get url() {
        return url
      },

      resolveDependency: (...args) => server.environments.client.pluginContainer.resolveId(...args),

      async adopt(nextSnapshot) {
        if (snapshot?.id === nextSnapshot.id) return

        const initialBuild = snapshot === undefined
        snapshot = nextSnapshot
        if (initialBuild) {
          // Dependencies were unavailable at startup; discard unresolved optimizer entries.
          await server.restart()
          const address = server.resolvedUrls?.local[0]
          if (!address) throw new Error('Renderer restart did not publish a listening address')
          url = address
        } else {
          server.moduleGraph.invalidateAll()
          server.ws.send({ type: 'full-reload' })
        }
      },

      watch(listener) {
        listeners.add(listener)
        return () => {
          listeners.delete(listener)
        }
      },

      close() {
        listeners.clear()
        return Promise.all([inputWatcher.close(), server.close()]).then(() => undefined)
      },
    }
  } catch (cause) {
    await Promise.all([inputWatcher.close(), server.close()])
    throw cause
  }
}

import { afterAll, beforeAll, expect, test, vi } from 'vitest'
import { copyFile, mkdir, mkdtemp, rm, writeFile } from 'node:fs/promises'
import { join, relative } from 'node:path'
import { fileURLToPath } from 'node:url'
import { startRenderer } from '../../tools/dev/renderer'

const paths = vi.hoisted(() => ({ appRoot: '', repositoryRoot: '' }))
// Only relocate owned files; use the actual Vite configuration, server and watcher.
vi.mock('../../tools/lib/paths', () => paths)

let renderer: Awaited<ReturnType<typeof startRenderer>> | undefined
const changes: string[] = []

beforeAll(async () => {
  const originalApp = fileURLToPath(new URL('../..', import.meta.url))
  await mkdir(join(originalApp, '.local'), { recursive: true })
  paths.repositoryRoot = await mkdtemp(join(originalApp, '.local', 'renderer-test-'))
  paths.appRoot = join(paths.repositoryRoot, 'clients/desktop/app')
  for (const directory of [
    'config/vite',
    'src/main',
    'src/preload',
    'src/extension-host',
    'src/shared',
    'native',
    'assets',
  ]) {
    await mkdir(join(paths.appRoot, directory), { recursive: true })
  }
  await copyFile(
    join(originalApp, 'config/vite/vite.config.renderer.ts'),
    join(paths.appRoot, 'config/vite/vite.config.renderer.ts'),
  )
  for (const name of ['main', 'reader', 'player', 'game-panel']) {
    const directory = join(paths.appRoot, 'src/renderer/windows', name)
    await mkdir(directory, { recursive: true })
    await writeFile(join(directory, 'index.html'), '<!doctype html><main>Watcher fixture</main>')
  }
  await writeFile(join(paths.appRoot, 'package.json'), '{"type":"module"}')
  await writeFile(join(paths.appRoot, 'config/vite/vite.config.main.ts'), 'export default {}\n')
  await writeFile(join(paths.repositoryRoot, 'pnpm-lock.yaml'), 'lockfileVersion: 9\n')
  const member = join(paths.repositoryRoot, 'package')
  await mkdir(join(member, 'config/typescript'), { recursive: true })
  await writeFile(join(member, 'package.json'), '{"name":"@kisaki3/watch-fixture"}')
  await writeFile(join(member, 'config/typescript/tsconfig.lib.json'), '{}\n')
  renderer = await startRenderer(
    [{ name: '@kisaki3/watch-fixture', path: member }],
    join(paths.repositoryRoot, 'snapshots'),
  )
  renderer.watch((change) => changes.push(change))
  // Initial adoption restarts Vite. Watch subscriptions must survive that real restart.
  await renderer.adopt({ id: 'empty-fixture', sizeBytes: 0, packages: new Map() })
})

afterAll(async () => {
  await renderer?.close()
  if (paths.repositoryRoot) {
    // Vite may still finish a cache write as its server closes; retry transient directory removal.
    await rm(paths.repositoryRoot, { recursive: true, force: true, maxRetries: 5, retryDelay: 200 })
  }
})

test('runtime configuration and nested public-package inputs remain watched after Vite restarts', async () => {
  for (const [path, content, kind] of [
    [
      join(paths.appRoot, 'config/vite/vite.config.main.ts'),
      'export default { mode: "development" }\n',
      'runtime',
    ],
    [
      join(paths.appRoot, 'package.json'),
      '{"type":"module","imports":{"#fixture":"./src/main/entry.ts"}}',
      'runtime',
    ],
    [
      join(paths.repositoryRoot, 'package/config/typescript/tsconfig.lib.json'),
      '{"compilerOptions":{"strict":true}}',
      'public-package',
    ],
    [join(paths.appRoot, 'src/main/added.ts'), 'export const value = 1\n', 'runtime'],
  ] as const) {
    const before = changes.filter((change) => change === kind).length
    await writeFile(path, content)
    await expect
      .poll(() => changes.filter((change) => change === kind).length, {
        message: `Expected ${kind} notification for ${relative(paths.repositoryRoot, path)}`,
      })
      .toBeGreaterThan(before)
  }
})
